<?php
namespace App\Http\Controllers;use App\Models\{Employee,AttendanceRecord,AdvancePayment,ExtraDuty,Payslip};class DashboardController extends Controller{public function __invoke(){return view('dashboard', ['employees'=>Employee::count(),'active'=>Employee::where('status','active')->count(),'present'=>AttendanceRecord::whereDate('attendance_date',today())->where('status','present')->count(),'absent'=>AttendanceRecord::whereDate('attendance_date',today())->where('status','absent')->count(),'hours'=>AttendanceRecord::whereMonth('attendance_date',now()->month)->sum('hours'),'advance'=>AdvancePayment::sum('amount'),'extra'=>ExtraDuty::where('approval_status','approved')->sum('amount'),'payable'=>Payslip::where('month',now()->month)->sum('net_salary')]);}}
